#include <chrono>
#include <condition_variable>
#include <cstdlib>
#include <iostream>
#include <mutex>
#include <thread>

using namespace Slic3r::GUI::JusPrin::Agent;
using nlohmann::json;

namespace {

// A 1x1 PNG.
constexpr const char* kPixel = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";

std::string openrouter_key()
{
    const char* key = std::getenv("OPENROUTER_API_KEY");
    return key == nullptr ? std::string() : std::string(key);
}

// What this process has spent, in OpenRouter credits (US dollars), and the
// most it may. A request's cost is known only once it returns, so one is
// refused unless the total plus a bound on its cost stays under the cap. The
// bound takes every two bytes of the body as an input token (JSON averages
// nearer four) and allows 16k output tokens, several times what any of these
// replies needs; the request sets no output limit of its own, so a reply
// longer than that is the one way past the cap.
constexpr double kSpendCap          = 0.50;
constexpr double kOutputAllowance   = 16000;
constexpr double kInputPricePerTok  = 0.75e-6; // openai/gpt-5.4-mini on OpenRouter, 2026-10-19
constexpr double kOutputPricePerTok = 4.5e-6;
std::mutex       g_spend_mutex;
double           g_spent{0};
int              g_requests{0};

// Reads the terminal event of one streamed response and logs what it cost:
// usage.cost when OpenRouter reports it, otherwise the listed price times
// the reported tokens, marked as computed.
void meter(int number, const std::string& stream, unsigned status, const std::string& error)
{
    json        terminal;
    std::size_t at = 0;
    while ((at = stream.find("data:", at)) != std::string::npos) {
        at += 5;
        const std::size_t end = stream.find('\n', at);
        const json        event = json::parse(stream.substr(at, end == std::string::npos ? std::string::npos : end - at), nullptr, false);
        if (event.is_object() && event.contains("response") &&
            (event.value("type", "") == "response.completed" || event.value("type", "") == "response.failed" ||
             event.value("type", "") == "response.incomplete"))
            terminal = event;
        else if (event.is_object() && event.value("type", "") == "error")
            terminal = event;
    }
    const json  response = terminal.contains("response") ? terminal["response"] : json::object();
    const json  usage    = response.value("usage", json::object());
    double      cost     = 0;
    std::string how      = "none reported";
    if (usage.contains("cost") && usage["cost"].is_number()) {
        cost = usage["cost"].get<double>();
        how  = "usage.cost";
    } else if (usage.contains("input_tokens")) {
        cost = usage.value("input_tokens", 0.0) * kInputPricePerTok + usage.value("output_tokens", 0.0) * kOutputPricePerTok;
        how  = "computed from tokens";
    }
    double total;
    {
        std::lock_guard<std::mutex> lock(g_spend_mutex);
        g_spent += cost;
        total = g_spent;
    }
    std::cerr << "LIVE REQUEST " << number << " status=" << status << (error.empty() ? "" : " error=" + error)
              << " terminal=" << terminal.value("type", "(none)") << " id=" << response.value("id", "")
              << " input_tokens=" << usage.value("input_tokens", 0) << " output_tokens=" << usage.value("output_tokens", 0)
              << " cost=$" << cost << " (" << how << ") running_total=$" << total << '\n';
    if (terminal.value("type", "") != "response.completed")
        std::cerr << "LIVE REQUEST " << number << " stream: " << stream.substr(0, 1500) << '\n';
}

// Sends one request through the app's real transport unless it could take
// the spend past the cap, logs what went out, and meters what came back.
bool metered_post(IAgentHttpTransport& transport, AgentHttpRequest request, IAgentHttpTransport::EventFn event)
{
    const double bound = request.body.size() / 2.0 * kInputPricePerTok + kOutputAllowance * kOutputPricePerTok;
    int          number;
    {
        std::lock_guard<std::mutex> lock(g_spend_mutex);
        if (g_spent + bound > kSpendCap) {
            std::cerr << "LIVE REQUEST refused: $" << g_spent << " spent, this one could cost $" << bound << ", cap $" << kSpendCap
                      << '\n';
            return false;
        }
        number = ++g_requests;
    }
    const json body = json::parse(request.body);
    std::cerr << "LIVE REQUEST " << number << " sent " << request.body.size() << " bytes to " << request.url
              << " model=" << body.value("model", "") << " tools=" << body.value("tools", json::array()).size()
              << " input_items=" << body.value("input", json::array()).size()
              << " parallel_tool_calls=" << body.value("parallel_tool_calls", json()).dump() << '\n';
    auto stream = std::make_shared<std::string>();
    return transport.post(std::move(request), [number, stream, event = std::move(event)](AgentHttpEvent http) {
        if (http.kind == AgentHttpEvent::Kind::Data)
            *stream += http.data;
        else
            meter(number, *stream, http.status, http.error);
        event(std::move(http));
    });
}

// The real transport, metered, with every request it posts kept for the test
// to read.
class RecordingTransport final : public IAgentHttpTransport
{
public:
    explicit RecordingTransport(std::vector<AgentHttpRequest>& sent) : m_sent(sent) {}
    bool post(AgentHttpRequest request, EventFn event) override
